import AppKit
import Defaults
import XCTest

@testable import Workroom

/// Store-level tests for the per-project "Run command" feature (issue #7). They drive a real,
/// non-singleton `AppStore` with the terminal factory seam overridden (so no live PTY) and capture
/// the command string handed to `makeView` to assert the shell wrap. Run-state lives on the store
/// (OV-A), so it's all inspectable here; the libghostty `command`/child-exit behaviour itself is
/// verified live (T1), and the toolbar/menu/sidebar wiring via XCUITest (T13).
@MainActor
final class RunCommandTests: XCTestCase {
  private var captured: [String?] = []
  private var signals: [(TerminalTarget.ID, Int32)] = []
  /// Windows registered on `WindowRegistry.shared` by the owner-focus test below — unlike every
  /// other test here, that one exercises the real singleton (not an injectable instance), so
  /// registrations must be unwound in `tearDown` (not just at the end of the test body) or a failed
  /// assertion could leak a stale registration into a later test (issue #127).
  private var registeredWindows: [NSWindow] = []

  override func setUp() {
    super.setUp()
    captured = []
    signals = []
    Defaults[.runCommands] = [:]
  }

  override func tearDown() {
    Defaults[.runCommands] = [:]
    for window in registeredWindows { WindowRegistry.shared.unregister(window: window) }
    registeredWindows = []
    super.tearDown()
  }

  private func makeStore(_ projects: [Project]) -> AppStore {
    let store = AppStore()
    // No close-confirm modal in a unit test. Per store, NOT via `Defaults[.confirmOnCloseTerminal]`:
    // parallel workers share one UserDefaults domain, so writing that key reached into the other
    // close-behaviour classes mid-body (see `AppStore.confirmOnCloseOverrideForTesting`).
    store.confirmOnCloseOverrideForTesting = false
    store.terminals.makeView = { [weak self] _, cwd, command in
      self?.captured.append(command)
      return GhosttySurfaceView(workingDirectory: cwd, command: command, spawnsSurface: false)
    }
    store.signalSupervisorForTesting = { [weak self] sig, id in
      self?.signals.append((id, sig))
      return true
    }
    store.projects = projects
    return store
  }

  /// A `makeStore` variant whose supervisor seam always returns `false` (dead supervisor), forcing
  /// `restartRunCommand` to take the respawn path rather than the signal path.
  private func makeStoreDeadSupervisor(_ projects: [Project]) -> AppStore {
    let store = AppStore()
    store.confirmOnCloseOverrideForTesting = false  // as in `makeStore`: never a modal
    store.terminals.makeView = { [weak self] _, cwd, command in
      self?.captured.append(command)
      return GhosttySurfaceView(workingDirectory: cwd, command: command, spawnsSurface: false)
    }
    store.signalSupervisorForTesting = { [weak self] sig, id in
      self?.signals.append((id, sig))
      return false
    }
    store.projects = projects
    return store
  }

  private func project(_ path: String, workrooms: [String]) -> Project {
    Project(
      path: path, vcs: "git",
      workrooms: workrooms.map {
        Workroom(name: $0, path: "\(path)/\($0)", vcsName: "workroom/\($0)", warnings: [])
      })
  }

  private func target(_ store: AppStore, _ project: String, _ name: String) -> TerminalTarget {
    store.target(for: .workroom(project: project, name: name))!
  }

  /// The run terminal's surface view (so a test can simulate supervisor exit via `handleChildExited`).
  private func runView(_ store: AppStore, _ target: TerminalTarget) -> GhosttySurfaceView? {
    store.runTabID(for: target.id).flatMap { store.terminals.tab($0, for: target)?.surface }
  }

  // MARK: Storage

  func testRunConfigRoundTripAndRemoval() {
    let store = makeStore([])
    let config = RunConfig(command: "npm run dev", autoRun: true)
    store.setRunConfig(config, forProject: "/a")
    XCTAssertEqual(store.runConfig(forProject: "/a"), config)
    XCTAssertTrue(store.hasRunCommand(forProject: "/a"))

    // A blank command with auto-run off removes the entry (no dead keys).
    store.setRunConfig(.empty, forProject: "/a")
    XCTAssertEqual(store.runConfig(forProject: "/a"), .empty)
    XCTAssertNil(Defaults[.runCommands]["/a"])

/// and, while the program has declared itself busy via OSC 9;4, treats the title repaint as a liveness
/// heartbeat that refreshes the safety timer. Agents repaint an animated title the whole time they
/// work but emit OSC 9;4 only at the edges, so this keeps the spinner alive across a long task while
/// still letting a genuinely silent program time out (issue #38). The title NEVER starts the busy
/// state on its own — it only extends one already set by OSC 9;4 (issue #28).
func handleTitleChange(_ title: String) {
  onTitleChange?(title)
  if progressActive { armProgressTimeout() }
}

/// Called by `GhosttyRuntimeAdapter` on `GHOSTTY_ACTION_SHOW_CHILD_EXITED` — the surface's child
/// process exited. Forwards to the host; only run tabs act on it (issue #7).
func handleChildExited(exitCode: UInt32) {
  onChildExited?(exitCode)
}

/// Whether the surface's child process has already exited (`wait_after_command` keeps such a pane
/// open). Lets the host skip the "stops any running process" close confirmation — there's nothing
/// left running to lose (issue #7). False before the surface exists.
var processHasExited: Bool {
  surface.map { ghostty_surface_process_exited($0) } ?? false
}

/// Test seam: forces `hasLiveProcess` (tests run with `spawnsSurface: false`, so there's no real
/// PTY to report a live child). Production leaves this nil and reads libghostty.
var liveProcessOverrideForTesting: Bool?

/// Whether a child process is still running in this surface — vs. already exited with the pane held
/// open by `wait_after_command`, or no surface yet. The run-command graceful stop (issue #7) keys
/// off this: only a LIVE process needs a Ctrl-C + wait-for-exit before its surface is freed, so that
/// a dev server (e.g. Puma) cleans up its pidfile/port instead of being orphaned by a bare
/// surface-free (a PTY hangup → SIGHUP, which Puma ignores → "A server is already running" later).
var hasLiveProcess: Bool {
  if let liveProcessOverrideForTesting { return liveProcessOverrideForTesting }
  return surface != nil && !processHasExited
}

/// Test seam: forces `didSpawnFail` (tests run with `spawnsSurface: false`, where a nil surface is
/// intentional, so the real check can't exercise the failed-spawn path). Production leaves this nil.
var spawnFailOverrideForTesting: Bool?

/// Whether an attempted surface spawn (`ensureSurfaceCreated`) failed — the libghostty surface
/// couldn't be created (issue #67 background run). Distinct from "process exited": this is "the
/// surface object itself doesn't exist after we tried to make one", so it's race-free against a
/// command that exits instantly. Always false for test views (`spawnsSurface == false`), where a nil
/// surface is intentional, so the run state machine's tests are unaffected (unless overridden).
var didSpawnFail: Bool {
  if let spawnFailOverrideForTesting { return spawnFailOverrideForTesting }
  return spawnsSurface && surface == nil
}

