private func makeRealProject(workroom name: String) -> (
  project: Project, root: String, wrPath: String
) {
  let root = NSTemporaryDirectory() + "wr-storm-\(UUID().uuidString)"
  let wrPath = "\(root)/.workrooms/\(name)"
